import type { ExportJobStatus } from "./enums";
import type { AssetId, CompositionId, LayerId, ProjectId, TrackItemId } from "./ids";
import type { Tick } from "./tick";

/**
 * Base shape for every event on the Event Bus. Every listener declares its
 * exact event type — no wildcard subscriptions. See STYLE_GUIDE.md and
 * docs/04-core/overview.md.
 */
export interface IEvent<TType extends string = string, TPayload = unknown> {
  readonly type: TType;
  readonly payload: TPayload;
  readonly timestamp: number;
}

export interface AppEventMap {
  LayerSelected: { layerIds: LayerId[] };
  LayerDeselected: { layerIds: LayerId[] };
  PlaybackStarted: { atTick: Tick };
  PlaybackPaused: { atTick: Tick };
  PlaybackStopped: Record<string, never>;
  PlaybackSeeked: { toTick: Tick };
  TrackItemMoved: { trackItemId: TrackItemId; toTick: Tick };
  TrackItemTrimmed: { trackItemId: TrackItemId; inTick: Tick; outTick: Tick };
  TrackItemSplit: { trackItemId: TrackItemId; atTick: Tick };
  TrackItemDeleted: { trackItemId: TrackItemId };
  CompositionOpened: { compositionId: CompositionId };
  ProjectSaved: { projectId: ProjectId };
  ProjectLoaded: { projectId: ProjectId };
  ExportProgressed: { jobId: string; status: ExportJobStatus; progress: number };
  ExportCompleted: { jobId: string };
  ExportFailed: { jobId: string; reason: string };
  CommandExecuted: { commandId: string };
  CommandUndone: { commandId: string };
  CommandRedone: { commandId: string };
  AssetImported: { assetId: AssetId };
  AssetImportFailed: { reason: string };
}

export type AppEventType = keyof AppEventMap;

export type AppEvent<TType extends AppEventType = AppEventType> = {
  [K in TType]: IEvent<K, AppEventMap[K]>;
}[TType];

/** See docs/08-layer-engine/overview.md */
export enum LayerType {
  Video = "Video",
  Image = "Image",
  Audio = "Audio",
  Text = "Text",
  Sticker = "Sticker",
  Shape = "Shape",
  Group = "Group",
}

/** See docs/07-timeline-engine/tracks.md */
export enum TrackType {
  Video = "Video",
  Audio = "Audio",
  Text = "Text",
  Shape = "Shape",
  Sticker = "Sticker",
  Camera = "Camera",
  Guide = "Guide",
  Adjustment = "Adjustment",
  Effect = "Effect",
}

export enum PlaybackState {
  Idle = "Idle",
  Playing = "Playing",
  Paused = "Paused",
  Seeking = "Seeking",
}

/** See docs/06-animation-engine/interpolation.md */
export enum InterpolationType {
  Linear = "Linear",
  Bezier = "Bezier",
  Step = "Step",
}

/** See docs/06-animation-engine/property-system.md */
export enum PropertyValueType {
  Number = "Number",
  Vector2 = "Vector2",
  Vector3 = "Vector3",
  Color = "Color",
  Boolean = "Boolean",
  Text = "Text",
  Gradient = "Gradient",
  Matrix = "Matrix",
}

/** See docs/05-rendering-engine/overview.md (ADR-004) */
export enum RenderBackend {
  WebGPU = "WebGPU",
  WebGL2 = "WebGL2",
  Canvas2D = "Canvas2D",
  Software = "Software",
}

/**
 * `Preset1080p30H264Opus` is the MVP preset per docs/24-roadmap/mvp.md Step
 * 1. The rest ship in Phase 10 alongside it — see docs/13-export/export-presets.md.
 * GIF is intentionally not a variant here: it isn't a WebCodecs/Mediabunny
 * target format at all (no video codec, needs palette quantization), so it
 * stays an open item rather than a fake enum value.
 */
export enum ExportPreset {
  Preset720p30H264Opus = "720p30-h264-opus",
  Preset1080p30H264Opus = "1080p30-h264-opus",
  Preset4K30H264Opus = "4k30-h264-opus",
  Preset1080p30VP9Opus = "1080p30-vp9-opus",
}

/** See docs/13-export/overview.md job state machine */
export enum ExportJobStatus {
  Queued = "Queued",
  Preparing = "Preparing",
  Rendering = "Rendering",
  Encoding = "Encoding",
  Muxing = "Muxing",
  Finished = "Finished",
  Cancelled = "Cancelled",
  Failed = "Failed",
}

/** See docs/11-ai/overview.md Capability Registry */
export enum AICapability {
  TextToSpeech = "TextToSpeech",
  BackgroundRemoval = "BackgroundRemoval",
  UpscaleImage = "UpscaleImage",
  SegmentPerson = "SegmentPerson",
  RemoveNoise = "RemoveNoise",
  EnhanceVoice = "EnhanceVoice",
}

/** See docs/16-plugin-system/overview.md lifecycle */
export enum PluginLifecycleState {
  Validating = "Validating",
  RequestingPermissions = "RequestingPermissions",
  Registered = "Registered",
  Initializing = "Initializing",
  Ready = "Ready",
}

/** See docs/09-effects-engine/overview.md */
export enum EffectType {
  GaussianBlur = "GaussianBlur",
  Glow = "Glow",
  DropShadow = "DropShadow",
  BlendMode = "BlendMode",
  ColorAdjustment = "ColorAdjustment",
  Transition = "Transition",
}

/** See docs/09-effects-engine/blend-modes.md — matches CSS `mix-blend-mode` names 1:1 where one exists. */
export enum BlendMode {
  Normal = "Normal",
  Multiply = "Multiply",
  Screen = "Screen",
  Overlay = "Overlay",
  SoftLight = "SoftLight",
  HardLight = "HardLight",
  Difference = "Difference",
  Darken = "Darken",
  Lighten = "Lighten",
  ColorDodge = "ColorDodge",
  ColorBurn = "ColorBurn",
}

/** See docs/09-effects-engine/transitions.md */
export enum TransitionType {
  CrossDissolve = "CrossDissolve",
  WipeLeft = "WipeLeft",
  WipeRight = "WipeRight",
  WipeUp = "WipeUp",
  WipeDown = "WipeDown",
}

