1	import {
2	  ExportJobStatus,
3	  type AppEventMap,
4	  type AppEventType,
5	  type Tick,
6	} from "@motion-studio/shared";
7	import { resolveAudioCodec, resolveVideoCodec, type IEncodeCapabilityProbe } from "./codecs";
8	import type {
9	  IAudioTrackSource,
10	  IExportAudioSource,
11	  IMuxerFactory,
12	  IMuxerOutput,
13	} from "./container";
14	import {
15	  computeExportFrames,
16	  type IExportFrameRenderer,
17	  type IFrameEvaluator,
18	} from "./frame-evaluator";
19	import type { IExportPreset } from "./presets";
20	
21	/**
22	 * Same generic shape as `packages/core/src/event-bus.ts`'s `EventBus.emit`
23	 * — a real `EventBus` instance satisfies this structurally, no adapter
24	 * needed, matching how `AudioEngine.attachRealtimeContext` takes a plain
25	 * `IAudioContext` rather than importing Core.
26	 */
27	export interface IExportEventSink {
28	  emit<T extends AppEventType>(type: T, payload: AppEventMap[T]): void;
29	}
30	
31	export interface IExportJobConfig {
32	  readonly jobId: string;
33	  readonly preset: IExportPreset;
34	  readonly composition: { readonly durationTicks: Tick; readonly fps: number };
35	  readonly tickResolution?: number;
36	  readonly signal?: AbortSignal;
37	}
38	
39	export interface IExportJobDependencies {
40	  readonly evaluator: IFrameEvaluator;
41	  readonly renderer: IExportFrameRenderer;
42	  readonly muxerFactory: IMuxerFactory;
43	  readonly capabilities: IEncodeCapabilityProbe;
44	  readonly audioSource?: IExportAudioSource;
45	  readonly events?: IExportEventSink;
46	}
47	
48	export interface IExportJobResult {
49	  readonly jobId: string;
50	  readonly status: ExportJobStatus.Finished | ExportJobStatus.Cancelled;
51	  readonly output?: ArrayBuffer;
52	}
53	
54	/**
55	 * Drives one export job through the state machine in
56	 * `docs/13-export/overview.md`: Preparing (capability resolution + muxer
57	 * setup) -> Rendering (per-frame evaluate+draw+encode, fused because
58	 * Mediabunny's track `add()` call *is* the encode step, per `container.ts`)
59	 * -> Encoding (bulk audio) -> Muxing (finalize) -> Finished. Never buffers
60	 * more than one frame at a time (PLAN.md Phase 10: "never buffer every
61	 * frame in memory") — each video frame is hashed into the muxer as soon as
62	 * it's rendered. Cancellation (`config.signal`) is checked before Preparing
63	 * commits and before every frame, matching "cancellation is safe at any
64	 * stage."
65	 */
66	export async function runExportJob(
67	  config: IExportJobConfig,
68	  deps: IExportJobDependencies,
69	): Promise<IExportJobResult> {
70	  const { jobId, preset, composition, signal } = config;
71	
72	  const emit = (status: ExportJobStatus, progress: number): void => {
73	    deps.events?.emit("ExportProgressed", { jobId, status, progress });
74	  };
75	
76	  try {
77	    emit(ExportJobStatus.Preparing, 0);
78	
79	    const videoCodec = await resolveVideoCodec(deps.capabilities, preset.videoCodec);
80	    const audioCodec = deps.audioSource
81	      ? await resolveAudioCodec(deps.capabilities, preset.audioCodec)
82	      : undefined;
83	    void videoCodec; // codec choice informs the host's real encoder construction; nothing left to do with it here
84	
85	    const output = deps.muxerFactory.createOutput();
86	    const videoTrack = deps.muxerFactory.createVideoTrackSource();
87	    output.addVideoTrack(videoTrack, { frameRate: preset.fps });
88	
89	    let audioTrack: IAudioTrackSource | undefined;
90	    if (deps.audioSource && audioCodec) {
91	      audioTrack = deps.muxerFactory.createAudioTrackSource();
92	      output.addAudioTrack(audioTrack);
93	    }
94	
95	    await output.start();
96	
97	    if (signal?.aborted) {
98	      return await cancelJob(output, jobId, emit);
99	    }
100	
101	    emit(ExportJobStatus.Rendering, 0);
102	    const frames = computeExportFrames(
103	      composition.durationTicks,
104	      composition.fps,
105	      preset.fps,
106	      config.tickResolution,
107	    );
108	
109	    for (const [index, frame] of frames.entries()) {
110	      if (signal?.aborted) {
111	        return await cancelJob(output, jobId, emit);
112	      }
113	      const frameState = await deps.evaluator.evaluate(frame.tick);
114	      await deps.renderer.renderFrame(frameState);
115	      await videoTrack.add(frame.timestampSeconds, frame.durationSeconds);
116	      emit(ExportJobStatus.Rendering, (index + 1) / frames.length);
117	    }
118	
119	    if (audioTrack && deps.audioSource) {
120	      emit(ExportJobStatus.Encoding, 0);
121	      await audioTrack.add(deps.audioSource, 0);
122	      emit(ExportJobStatus.Encoding, 1);
