14	    protected readonly vfs: IVFS,
15	    protected readonly directory: string,
16	  ) {}
17	
18	  async create(item: T): Promise<void> {
19	    await this.write(item);
20	  }
21	
22	  async update(item: T): Promise<void> {
23	    await this.write(item);
24	  }
