27	    await this.vfs.delete(this.pathFor(id));
28	  }
29	
30	  async get(id: string): Promise<T | undefined> {
31	    const data = await this.vfs.read(this.pathFor(id));
32	    return data ? this.deserialize(data) : undefined;
33	  }
34	
35	  async list(): Promise<T[]> {
36	    const paths = await this.vfs.list(`${this.directory}/`);
37	    const items: (T | undefined)[] = await Promise.all(
38	      paths.map(async (path): Promise<T | undefined> => {
39	        const data = await this.vfs.read(path);
40	        return data ? this.deserialize(data) : undefined;
41	      }),
42	    );
43	    return items.filter((item): item is T => item !== undefined);
44	  }
45	
46	  protected pathFor(id: string): string {
47	    return `${this.directory}/${id}.json`;
48	  }
49	
50	  private deserialize(data: Uint8Array): T {
51	    return decodeJson<T>(data);
52	  }
53	
54	  private async write(item: T): Promise<void> {
55	    await this.vfs.write(this.pathFor(item.id), encodeJson(item));
56	  }
