import type { AssetId, AssetType, Tick } from "@motion-studio/shared";

/**
 * One row per imported asset. PLAN.md Phase 12 "Asset catalog": id, name,
 * type, size, duration, contentHash, tags, createdAt. `id` doubles as the
 * dedup key — the import pipeline derives it from `contentHash`, so
 * re-importing identical bytes resolves to the same `id` (PLAN.md "Dedup
 * by content hash"), never a second catalog row.
 */
export interface IAssetCatalogEntry {
  readonly id: AssetId;
  readonly name: string;
  readonly type: AssetType;
  readonly mimeType: string;
  readonly sizeBytes: number;
  /** Present for Video/Audio only. */
  readonly durationTicks?: Tick;
  readonly contentHash: string;
  readonly tags: readonly string[];
  readonly createdAt: number;
}

/**
 * Structurally matches `@motion-studio/storage`'s `IRepository<T>` shape
 * (`create/update/delete/get/list`) so a real `JsonRepository<IAssetCatalogEntry>`
 * satisfies this without `@motion-studio/assets` importing `@motion-studio/storage`
 * — same DI convention as `IAssetBlobStore`. No real backing store wired yet.
 */
export interface IAssetCatalogStore {
  create(entry: IAssetCatalogEntry): Promise<void>;
  delete(id: AssetId): Promise<void>;
  get(id: AssetId): Promise<IAssetCatalogEntry | undefined>;
  list(): Promise<IAssetCatalogEntry[]>;
}

/**
 * Thin query layer over `IAssetCatalogStore` — the "single source of truth
 * for all assets" (PLAN.md). Per ADR-002, `17-ui/asset-browser.md` reads
 * through this and keeps no registry of its own.
 */
export class AssetCatalog {
  constructor(private readonly store: IAssetCatalogStore) {}

  register(entry: IAssetCatalogEntry): Promise<void> {
    return this.store.create(entry);
  }

  get(id: AssetId): Promise<IAssetCatalogEntry | undefined> {
    return this.store.get(id);
  }

  remove(id: AssetId): Promise<void> {
    return this.store.delete(id);
  }

  list(): Promise<IAssetCatalogEntry[]> {
    return this.store.list();
  }
}

import { AssetType, createAssetId } from "@motion-studio/shared";
import { describe, expect, it } from "vitest";
import { AssetCatalog, type IAssetCatalogEntry } from "./asset-catalog";
import { FakeAssetCatalogStore } from "./test-support/fakes";

function makeEntry(id: string): IAssetCatalogEntry {
  return {
    id: createAssetId(id),
    name: `asset-${id}`,
    type: AssetType.Image,
    mimeType: "image/png",
    sizeBytes: 1024,
    contentHash: id,
    tags: [],
    createdAt: 0,
  };
}

describe("AssetCatalog", () => {
  it("registers and retrieves an entry", async () => {
    const catalog = new AssetCatalog(new FakeAssetCatalogStore());
    const entry = makeEntry("a");

    await catalog.register(entry);

    expect(await catalog.get(entry.id)).toEqual(entry);
  });

  it("lists all registered entries", async () => {
    const catalog = new AssetCatalog(new FakeAssetCatalogStore());
    await catalog.register(makeEntry("a"));
    await catalog.register(makeEntry("b"));

    const all = await catalog.list();

    expect(all.map((entry) => entry.id).sort()).toEqual(["a", "b"]);
  });

  it("removes an entry", async () => {
    const catalog = new AssetCatalog(new FakeAssetCatalogStore());
    const entry = makeEntry("a");
    await catalog.register(entry);

    await catalog.remove(entry.id);

    expect(await catalog.get(entry.id)).toBeUndefined();
  });
});

import { AssetType, type Tick } from "@motion-studio/shared";

/** Per-type metadata schemas — PLAN.md Phase 12, `docs/14-assets/metadata.md`. */
export interface IVideoMetadata {
  readonly type: AssetType.Video;
  readonly width: number;
  readonly height: number;
  readonly durationTicks: Tick;
  readonly fps: number;
  readonly hasAudio: boolean;
}

export interface IImageMetadata {
  readonly type: AssetType.Image;
  readonly width: number;
  readonly height: number;
}

export interface IAudioMetadata {
  readonly type: AssetType.Audio;
  readonly durationTicks: Tick;
  readonly sampleRate: number;
  readonly numberOfChannels: number;
}

export interface IFontMetadata {
  readonly type: AssetType.Font;
  readonly family: string;
}

/** `size` is the cube edge length (e.g. 33 for a 33x33x33 `.cube` LUT). */
export interface ILUTMetadata {
  readonly type: AssetType.LUT;
  readonly size: number;
}

export type IAssetMetadata =
  | IVideoMetadata
  | IImageMetadata
  | IAudioMetadata
  | IFontMetadata
  | ILUTMetadata;

/**
 * Decode-and-inspect step of the import pipeline
 * (`docs/14-assets/importer.md`). No real decoder wired yet — same
 * "engine exists, integration is later" gap as Rendering/Effects/Audio's
 * backend DI.
 */
export interface IMetadataExtractor {
  extract(data: Uint8Array, type: AssetType, mimeType: string): Promise<IAssetMetadata>;
}

